$ErrorActionPreference = 'Stop'
$root = 'C:\dev\nial_diary'
$mainPath = Join-Path $root 'lib\main.dart'
$pubPath = Join-Path $root 'pubspec.yaml'
$manifestPath = Join-Path $root 'android\app\src\main\AndroidManifest.xml'
if ((Get-FileHash -LiteralPath $mainPath -Algorithm SHA256).Hash -ne '270877DBB99FE62D24808ADC2753073497E56D8D37BE861CB43A013DD0F81B85') {
  throw 'main.dart differs from uploaded source or voice is already installed. No changes saved.'
}
if ((Get-FileHash -LiteralPath $pubPath -Algorithm SHA256).Hash -ne '0D26F14F27A27AE1F9CC8EF1508A284801C1AE50B1A4A56549DC6A331599DBA9') {
  throw 'pubspec.yaml differs from uploaded source. No changes saved.'
}
$manifest = [IO.File]::ReadAllText($manifestPath)
[xml]$xml = $manifest
if ($null -eq $xml.manifest.application -or $null -eq $xml.manifest.application.activity) {
  throw 'Main manifest must contain application and activity. No changes saved.'
}
if (!$manifest.Contains('android.permission.RECORD_AUDIO')) {
  $rx = [regex]::new('<manifest\b[^>]*>')
  $hit = $rx.Match($manifest)
  if (!$hit.Success) { throw 'Manifest header not found. No changes saved.' }
  $at = $hit.Index + $hit.Length
  $manifest = $manifest.Substring(0, $at) + "`n    <uses-permission android:name=`"android.permission.RECORD_AUDIO`" />" + $manifest.Substring($at)
}
[xml]$checkedManifest = $manifest
$mainEncoded = @'

'@
$pubEncoded = @'

'@
$newMain = [Convert]::FromBase64String($mainEncoded.Trim())
$newPub = [Convert]::FromBase64String($pubEncoded.Trim())
$backup = Join-Path $root ('backups\before_voice_' + (Get-Date -Format 'yyyyMMdd_HHmmss_fff'))
New-Item -ItemType Directory -Path $backup -Force | Out-Null
Copy-Item -LiteralPath $mainPath -Destination (Join-Path $backup 'main.dart.bak')
Copy-Item -LiteralPath $pubPath -Destination (Join-Path $backup 'pubspec.yaml.bak')
Copy-Item -LiteralPath $manifestPath -Destination (Join-Path $backup 'AndroidManifest.xml.bak')
try {
  [IO.File]::WriteAllBytes($mainPath, $newMain)
  [IO.File]::WriteAllBytes($pubPath, $newPub)
  [IO.File]::WriteAllText($manifestPath, $manifest, [Text.UTF8Encoding]::new($false))
} catch {
  Copy-Item -LiteralPath (Join-Path $backup 'main.dart.bak') -Destination $mainPath -Force
  Copy-Item -LiteralPath (Join-Path $backup 'pubspec.yaml.bak') -Destination $pubPath -Force
  Copy-Item -LiteralPath (Join-Path $backup 'AndroidManifest.xml.bak') -Destination $manifestPath -Force
  throw
}
Write-Host 'SUCCESS: voice notes installed. Run flutter pub get, dart format and flutter analyze.'
Write-Host "Source backups: $backup"
